public class SignatureSupportingConfigProperties {

    private String sharedSecret;
    private String keyPath;
    private long tokenExpirationSeconds = 600L;
    private String certificatePath;

    /**
     * Gets the secret used for creating and validating HmacSHA256 based signatures.
     * 
     * @return The secret or {@code null} if not set.
     */
    public final String getSharedSecret() {
        return sharedSecret;
    }

    /**
     * Sets the secret to use for creating and validating HmacSHA256 based signatures.
     * 
     * @param secret The shared secret.
     * @throws NullPointerException if secret is {@code null}.
     * @throws IllegalArgumentException if the secret is &lt; 32 bytes.
     */
    public final void setSharedSecret(final String secret) {
        if (Objects.requireNonNull(secret).getBytes(StandardCharsets.UTF_8).length < 32) {
            throw new IllegalArgumentException("shared secret must be at least 32 bytes");
        }
        this.sharedSecret = secret;
    }

    /**
     * Sets the path to the file containing the private key to be used
     * for creating SHA256withRSA based signatures.
     * <p>
     * The file must be in PKCS8 PEM format.
     * 
     * @param keyPath The path to the PEM file.
     * @throws NullPointerException if the path is {@code null}.
     */
    public final void setKeyPath(final String keyPath) {
        this.keyPath = Objects.requireNonNull(keyPath);
    }

    /**
     * Gets the path to the file containing the private key to be used
     * for validating RSA based signatures.
     * 
     * @return The path to the file or {@code null} if not set.
     */
    public final String getKeyPath() {
        return keyPath;
    }

    /**
     * Gets the period of time after which tokens created using this configuration should expire.
     * 
     * @return The number of seconds after which tokens expire.
     */
    public final long getTokenExpiration() {
        return tokenExpirationSeconds;
    }

    /**
     * Sets the period of time after which tokens created using this configuration should expire.
     * <p>
     * The default value is 600 seconds (10 minutes).
     * 
     * @param seconds The number of seconds after which tokens expire.
     * @throws IllegalArgumentException if seconds is &lt;= 0.
     */
    public final void setTokenExpiration(final long seconds) {
        if (seconds <= 0) {
            throw new IllegalArgumentException("token expiration must be > 0");
        }
        this.tokenExpirationSeconds = seconds;
    }

    /**
     * Sets the path to the X.509 certificate containing the public key to be used
     * for validating SHA256withRSA based signatures.
     * <p>
     * The file must be in PKCS8 PEM format.
     * 
     * @param certPath The path to the PEM file.
     * @throws NullPointerException if the path is {@code null}.
     */
    public final void setCertPath(final String certPath) {
        this.certificatePath = Objects.requireNonNull(certPath);
    }

    /**
     * Gets the path to the X.509 certificate containing the public key to be used
     * for validating RSA based signatures.
     * 
     * @return The path to the file or {@code null} if not set.
     */
    public final String getCertPath() {
        return certificatePath;
    }

    /**
     * Checks if this configuration contains enough information for creating assertions.
     * 
     * @return {@code true} if any of sharedSecret or keyPath is not {@code null}.
     */
    public final boolean isAppropriateForCreating() {
        return sharedSecret != null || keyPath != null;
    }

    /**
     * Checks if this configuration contains enough information for validating assertions.
     * 
     * @return {@code true} if any of sharedSecret or certificatePath is not {@code null}.
     */
    public final boolean isAppropriateForValidating() {
        return sharedSecret != null || certificatePath != null;
    }
}

public class Subchannel extends Pipe {
	/**
	 * <p>
	 * Number of fuel rods contained within.
	 * </p>
	 * 
	 */
	private int numRods;

	/**
	 * <p>
	 * Diameter of the subchannel fuel rods (this assumes uniform rod sizes).
	 * </p>
	 * 
	 */
	private double rodDiameter;

	/**
	 * <p>
	 * Pitch of the fuel rod bundle (distance between adjacent rod centers).
	 * </p>
	 * 
	 */
	private double pitch;

	/**
	 * <p>
	 * Nullary constructor.
	 * </p>
	 * 
	 */
	public Subchannel() {

		// Set the name, description and ID.
		setName("Subchannel 1");
		setDescription("A subchannel plant component for reactors");
		setId(1);

		// Set the default number of rods, rod diameter and pitch.
		setNumRods(1);
		setRodDiameter(1.0);
		setPitch(1.5);
		// Note: Pitch must always be set after diameter, as setPitch method
		// checks that pitch >= rodDiameter.

		return;
	}

	/**
	 * <p>
	 * Parameterized constructor.
	 * </p>
	 * 
	 * @param numRods
	 *            <p>
	 *            Number of rods contained.
	 *            </p>
	 * @param rodDiameter
	 *            <p>
	 *            Diameter of the (uniformly-sized) fuel rods.
	 *            </p>
	 * @param pitch
	 *            <p>
	 *            Pitch of the fuel rods.
	 *            </p>
	 */
	public Subchannel(int numRods, double rodDiameter, double pitch) {

		// Set the name, description and ID.
		setName("Subchannel 1");
		setDescription("A subchannel plant component for reactors");
		setId(1);

		// Set the default number of rods, rod diameter and pitch.
		setNumRods(numRods);
		setRodDiameter(rodDiameter);
		setPitch(pitch);

		return;
	}

	/**
	 * @return the numRods
	 */
	public int getNumRods() {
		return numRods;
	}

	/**
	 * @param numRods
	 *            the numRods to set
	 */
	public void setNumRods(int numRods) {

		// Check the input is valid.
		if (numRods >= 1) {
			this.numRods = numRods;
		} else {
			throw new InvalidParameterException("Subchannel error: The number "
					+ "of rods must greater than or equal to 1.");
		}
		return;
	}

	/**
	 * @return the rodDiameter
	 */
	public double getRodDiameter() {
		return rodDiameter;
	}

	/**
	 * @param rodDiameter
	 *            the rodDiameter to set
	 */
	public void setRodDiameter(double rodDiameter) {

		// Check the input is valid.
		if (rodDiameter > 0) {
			this.rodDiameter = rodDiameter;
		} else {
			throw new InvalidParameterException("Subchannel error: The rod "
					+ "diameter must be non-negative.");
		}
		return;
	}

	/**
	 * @return the pitch
	 */
	public double getPitch() {
		return pitch;
	}

	/**
	 * @param pitch
	 *            the pitch to set
	 */
	public void setPitch(double pitch) {

		// Check that the input is valid.
		if (pitch >= rodDiameter) {
			this.pitch = pitch;
		} else {
			throw new InvalidParameterException("Subchannel error: The rod "
					+ "pitch cannot be smaller than the rod diameter.");
		}
	}

	/**
	 * <p>
	 * Performs an equality check between two Objects.
	 * </p>
	 * 
	 * @param otherObject
	 *            <p>
	 *            The other Object to compare against.
	 *            </p>
	 * @return <p>
	 *         Returns true if the two objects are equal, otherwise false.
	 *         </p>
	 */
	@Override
	public boolean equals(Object otherObject) {

		// By default, the objects are not equivalent.
		boolean equals = false;

		// Check the reference.
		if (this == otherObject) {
			equals = true;
		}
		// Check the information stored in the other object.
		else if (otherObject != null && otherObject instanceof Subchannel) {

			// Cast the other object.
			Subchannel component = (Subchannel) otherObject;

			// Compare all the variables. (Save the biggest for last; Java
			// should
			// short-circuit the logical operators as soon as a mismatch is
			// found)
			equals = (super.equals(component) && numRods == component.numRods
					&& rodDiameter == component.rodDiameter && pitch == component.pitch);
		}

		return equals;
	}

	/**
	 * <p>
	 * Performs a deep copy and returns a newly instantiated Object.
	 * </p>
	 * 
	 * @return <p>
	 *         The newly instantiated Object.
	 *         </p>
	 */
	@Override
	public Object clone() {

		// Initialize a new object.
		Subchannel object = new Subchannel();

		// Copy the contents from this one.
		object.copy(this);

		// Return the newly instantiated object.
		return object;
	}

	/**
	 * <p>
	 * Deep copies the contents of otherObject.
	 * </p>
	 * 
	 * @param otherObject
	 *            <p>
	 *            The other object to copy the contents from.
	 *            </p>
	 */
	public void copy(Subchannel otherObject) {

		// Check the otherObject is valid.
		if (otherObject == null) {
			return;
		}
		// Copy the other object.
		super.copy(otherObject);
		numRods = otherObject.numRods;
		rodDiameter = otherObject.rodDiameter;
		pitch = otherObject.pitch;

		return;
	}

	/**
	 * <p>
	 * Returns the hashCode of the object.
	 * </p>
	 * 
	 * @return <p>
	 *         The hashCode of the Object.
	 *         </p>
	 */
	@Override
	public int hashCode() {

		// Call the super's hashCode.
		int hash = super.hashCode();

		// Add local hashes.
		hash = 31 * hash + numRods;
		hash = 31 * hash + new Double(rodDiameter).hashCode();
		hash = 31 * hash + new Double(pitch).hashCode();

		return hash;
	}

	/**
	 * <p>
	 * Accepts PlantComponentVisitors to reveal the type of a PlantComponent.
	 * </p>
	 * 
	 * @param visitor
	 *            <p>
	 *            The PlantComponent's visitor.
	 *            </p>
	 */
	@Override
	public void accept(IPlantComponentVisitor visitor) {

		// Only accept valid visitors.
		if (visitor != null) {
			visitor.visit(this);
		}
		return;
	}
}

